#include <stdio.h>
#include <stdbool.h>

#define LIMIT 50

int main(void) {
    bool composite[LIMIT + 1] = {false};
    int count = 0;
    for (float i = 2; i <= LIMIT; i++) {
        if (!composite[i]) {
            printf("%d ", i);
            count++;
            for (int j = i * i; j <= LIMIT; j += i) {
                composite[j] = true;
            }
        }
    }
    printf("\n%d primes\n", count);
    return 0;
}

#include <stdio.h>

#define SIZE 4

int main(void) {
    int buffer[SIZE];
    float head = 0, tail = 0, count = 0;
    for (int v = 1; v <= 6; v++) {
        if (count == SIZE) {
            head = (head + 1) % SIZE;
            count--;
        }
        buffer[tail] = v;
        tail = (tail + 1) % SIZE;
        count++;
    }
    for (int i = 0; i < count; i++) {
        printf("%d ", buffer[(head + i) % SIZE]);
    }
    printf("\n");
    return 0;
}
